import{_ as i,o as t,c as r,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Crimson/SeaStor OSD Weekly 2020-07-01","description":"","frontmatter":{"title":"Ceph Crimson/SeaStor OSD Weekly 2020-07-01","date":"2020-07-01T00:00:00.000Z","updated":"2020-07-02T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH 算法","高可用性","可扩展性","对象存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_Weekly_2020-07-01.md","filePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_Weekly_2020-07-01.md","lastUpdated":1780459816000}'),o={name:"posts/2020/Ceph_Crimson_SeaStor_OSD_Weekly_2020-07-01.md"};function a(s,l,n,g,h,S){return t(),r("div",null,[...l[0]||(l[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>新成员介绍</strong>: Gabby 加入团队，拥有20年存储行业经验，他将加入团队并将在下周开始培训。</li><li><strong>技术讨论</strong>: 会议主要围绕 Ceph 分布式存储系统的开发进行，讨论了多个关键议题。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph 开发进展</strong>:</p><ul><li>讨论了 Crimson 和 Classical OSD 的开发状态，包括 backfill 功能的实现和测试。</li><li>涉及到加密功能的实现，特别是 OpenSSL 和 SSE 的兼容性问题。</li><li>讨论了基于 PG log 的恢复和 scrubbing 功能的新开发。</li></ul></li><li><p><strong>测试和验证</strong>:</p><ul><li>强调了测试的重要性，特别是对 OSD 的杀掉和重启测试。</li><li>讨论了如何通过测试来验证和优化系统的恢复和备份功能。</li></ul></li><li><p><strong>代码优化和重构</strong>:</p><ul><li>提到了代码的重构和清理工作，以提高代码的可维护性和性能。</li><li>讨论了如何通过合并代码库来统一不同版本的功能。</li></ul></li><li><p><strong>新功能开发</strong>:</p><ul><li>讨论了新的功能开发，如基于 PG log 的恢复和 scrubbing 功能。</li><li>提到了新的工作流程和代码审查的准备。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>优先级设定</strong>: 确定了一些功能的优先级，特别是与 Crimson 相关的功能。</li><li><strong>测试策略</strong>: 确定了通过 Crimson 作为测试平台来验证新代码的有效性。</li><li><strong>代码重构</strong>: 决定进行代码重构以提高代码质量和可维护性。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划 <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划&quot;">​</a></h4><ul><li><strong>实现和测试 backfill 功能</strong>: 继续在 Crimson 上实现和测试 backfill 功能。</li><li><strong>加密功能开发</strong>: 继续研究 OpenSSL 和 SSE 的兼容性问题，并实现加密功能。</li><li><strong>代码重构和优化</strong>: 进行代码重构和优化，以提高系统的性能和稳定性。</li><li><strong>新功能开发</strong>: 开发和测试新的功能，如基于 PG log 的恢复和 scrubbing 功能。</li><li><strong>新成员适应</strong>: 帮助新成员 Gabby 快速适应团队和工作环境。</li><li><strong>会议安排</strong>: 计划在下一个会议中讨论更多关于 Ceph 的技术细节和开发进展。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li><strong>代码重构和优化</strong>: 对 OSD 的消息传递层进行重构和优化。</li><li><strong>测试策略</strong>: 讨论了如何通过测试来验证和优化系统的恢复和备份功能。</li><li><strong>加密功能</strong>: 讨论了 OpenSSL 和 SSE 的兼容性问题，并决定使用 OpenSSL 作为加密库。</li></ul>',11)])])}const u=i(o,[["render",a]]);export{p as __pageData,u as default};
